pub fn t(key: &str) -> &'static str {
    let l = LANG.get();
    T.iter().find(|r| r[0] == key).map(|r| r[l + 1]).unwrap_or_else(|| {
        eprintln!("skinvas: missing translation {key}");
        "?"
    })
}

#[cfg(test)]
mod tests {
    #[test]
    fn keys_are_unique() {
        let mut k: Vec<_> = super::T.iter().map(|r| r[0]).collect();
        k.sort();
        let n = k.len();
        k.dedup();
        assert_eq!(n, k.len());
    }
}
